  16: 
  17: package com.android.car.voicecontrol.runtime;
  18: import java.util.HashSet; import java.util.Set;
  19: public final class AudioInterruptionPolicy {
  20:     private final Set<String> exclusive=new HashSet<>();
  21:     public AudioInterruptionPolicy(){exclusive.add("emergency");exclusive.add("safety");exclusive.add("call");}
  22:     public boolean canInterrupt(String current,String requested){
  23:         if(requested==null)return false;if(current==null)return true;
  24:         return exclusive.contains(requested)||(!exclusive.contains(current)&&!current.equals(requested));
  25:     }
  26: }
