  16: 
  17: package com.android.car.voicecontrol.runtime;
  18: import java.util.Collections; import java.util.HashSet; import java.util.Set;
  19: public final class VoiceRuntimeCoordinator implements AutoCloseable {
  20:     private final VoiceCommandRouter router=new VoiceCommandRouter();
  21:     private final VoiceSessionLedger ledger=new VoiceSessionLedger(200);
  22:     private final AudioInterruptionPolicy interruptions=new AudioInterruptionPolicy();
  23:     private boolean closed;
  24:     public synchronized VoiceRoute accept(VoiceCommand command){
  25:         if(closed)throw new IllegalStateException("closed");VoiceRoute route=router.route(command);
  26:         ledger.append(command.userId+":"+route.domain+":"+route.operation);return route;
  27:     }
  28:     public synchronized Set<String> filterSupported(Set<String> actions){
  29:         if(closed)return Collections.emptySet();return new HashSet<>(actions);
  30:     }
  31:     public void recordContactLookup(String query){accept(new VoiceCommand("contact",query,-1,System.currentTimeMillis()));}
  32:     public VoiceSessionLedger ledger(){return ledger;}
  33:     public AudioInterruptionPolicy interruptions(){return interruptions;}
  34:     @Override public synchronized void close(){closed=true;ledger.clear();}
  35: }
