  18: import java.util.ArrayDeque; import java.util.ArrayList; import java.util.List;
  19: public final class VoiceSessionLedger {
  20:     private final int capacity; private final ArrayDeque<String> entries=new ArrayDeque<>();
  21:     public VoiceSessionLedger(int capacity){if(capacity<1)throw new IllegalArgumentException("capacity");this.capacity=capacity;}
  22:     public synchronized void append(String value){if(entries.size()==capacity)entries.removeFirst();entries.addLast(value);}
  23:     public synchronized List<String> snapshot(){return new ArrayList<>(entries);}
  24:     public synchronized void clear(){entries.clear();}
  25: }

