  35: import androidx.annotation.Nullable;
  36: import androidx.core.app.NotificationCompat;
  37: 
  38: import com.android.car.assist.CarVoiceInteractionSession;
  39: import com.android.car.voicecontrol.runtime.VoiceRuntimeCoordinator;
  40: import com.android.car.telephony.common.Contact;
  41: 
  42: import java.util.Arrays;
  43: import java.util.HashSet;
  44: import java.util.List;
  45: import java.util.Set;
  46: 
  47: /**
  48:  * Voice interaction entry point. This service is kept running for as long as this application
  49:  * is set as the default voice interaction service.
  50:  */
  51: public class InteractionService extends VoiceInteractionService {
  52:     private static final String TAG = "Mica.InteractionService";
  53:     private static final String CHANNEL_ID = "Mica";
  54:     private static final int NOTIFICATION_ID = 1;
  55:     private NotificationManager mNotificationManager;
  56:     public static final String LOCAL_SERVICE_ACTION = "com.android.car.voicecontrol.local";
  57:     public static final String LOCAL_SERVICE_CMD_SETUP_CHANGED = "setup-changed";
  58:     private static final List<String> SUPPORTED_VOICE_ACTIONS = Arrays.asList(
  59:             CarVoiceInteractionSession.VOICE_ACTION_READ_NOTIFICATION,
  60:             CarVoiceInteractionSession.VOICE_ACTION_REPLY_NOTIFICATION,
  61:             CarVoiceInteractionSession.VOICE_ACTION_HANDLE_EXCEPTION,
  62:             CarVoiceInteractionSession.VOICE_ACTION_SEND_SMS
  63:     );
  64:     public static final List<String> REQUIRED_PERMISSIONS = Arrays.asList(
  65:             Manifest.permission.RECORD_AUDIO,
  66:             Car.PERMISSION_SPEED,
  67:             Manifest.permission.CALL_PHONE,
  68:             Manifest.permission.READ_PHONE_STATE,
  69:             Manifest.permission.SEND_SMS,
  70:             Manifest.permission.READ_CONTACTS
  71:     );
  72:     private ContactsProvider mContactsProvider;
  73:     private VoiceRuntimeCoordinator mVoiceRuntime;
  74: 
  75:     private final ILocalService.Stub mBinder = new ILocalService.Stub() {
  76:         @Override
  77:         public boolean isSetupComplete() {
  78:             return InteractionService.this.isSetupComplete();
  79:         }
  80: 
  81:         @Override
  82:         public void registerListener(ILocalServiceListener listener) {
  83:             mListeners.register(listener);
  84:         }
  85: 
  86:         @Override
  87:         public void unregisterListener(ILocalServiceListener listener) {
  88:             mListeners.unregister(listener);
  89:         }
  90: 
  91:         @Override
  92:         public String getVoice() {
  93:             return PreferencesController.getInstance(InteractionService.this).getVoice();
  94:         }
  95: 
  96:         @Override
  97:         public void setVoice(String name) {
  98:             PreferencesController.getInstance(InteractionService.this).setVoice(name);
  99:         }
 100: 
 101:         @Override
 102:         public String getUsername() {
 103:             String value = PreferencesController.getInstance(InteractionService.this).getUsername();
 104:             Log.d(TAG, "getUsername(): " + value);
 105:             return value;
 106:         }
 107: 
 108:         @Override
 109:         public void setUsername(String value) {
 110:             Log.d(TAG, "setUsername: " + value);
 111:             PreferencesController.getInstance(InteractionService.this).setUsername(value);
 112:             onSetupChanged();
 113:         }
 114: 
 115:         @Override
 116:         public boolean hasAllPermissions() {
 117:             return InteractionService.hasAllPermissions(InteractionService.this);
 118:         }
 119: 
 120:         @Override
 121:         public boolean isNotificationListener() {
 122:             return InteractionService.this.isNotificationListener();
 123:         }
 124: 
 125:         @Override
 126:         public Contact getContact(String query, @Nullable String deviceAddress) {
 127:             mVoiceRuntime.recordContactLookup(query);
 128:             return mContactsProvider.getContact(query, deviceAddress);
 129:         }
 130:     };
 131:     private final RemoteCallbackList<ILocalServiceListener> mListeners = new RemoteCallbackList<>();
 132: 
 133:     @Override
 134:     public IBinder onBind(Intent intent) {
 135:         Log.d(TAG, "onBind: " + intent);
 136:         if (LOCAL_SERVICE_ACTION.equals(intent.getAction())) {
 137:             return mBinder;
 138:         }
 139:         return super.onBind(intent);
 140:     }
 141: 
 142:     @Override
 143:     public int onStartCommand(Intent intent, int flags, int startId) {
 144:         switch (intent.getAction()) {
 145:             case LOCAL_SERVICE_CMD_SETUP_CHANGED:
 146:                 onSetupChanged();
 147:                 return START_NOT_STICKY;
 148:             default:
 149:                 return super.onStartCommand(intent, flags, startId);
 150:         }
 151:     }
 152: 
 153:     @Override
 154:     public void onCreate() {
 155:         super.onCreate();
 156:         mContactsProvider = new ContactsProvider(this);
 157:         mVoiceRuntime = new VoiceRuntimeCoordinator();
 158:     }
 159: 
 160:     @Override
 161:     public void onDestroy() {
 162:         mContactsProvider.destroy();
 163:         mVoiceRuntime.close();
 164:         super.onDestroy();
 165:     }
 166: 
 167:     @Override
 168:     public void onReady() {
 169:         Log.e(TAG, "onReady()");
 170:         super.onReady();
 171:         updateNotification();
 172: 
 173:         // Setup always-on hot-word detector here (see: VoiceInteractionService#onReady()) for
 174:         // details.
 175:     }
 176: 
 177:     private boolean isSetupComplete() {
 178:         boolean setupComplete = PreferencesController.getInstance(this).isUserSignedIn()
 179:                 && hasAllPermissions(this) && isNotificationListener();
 180:         Log.d(TAG, "isSetupComplete: " + setupComplete);
 181:         return setupComplete;
 182:     }
 183: 
 184:     /**
 185:      * @return true if this application has all required dangerous permissions (permissions the
 186:      * user is able to grant).
 187:      */
 188:     public static boolean hasAllPermissions(Context context) {
 189:         for (String permission : REQUIRED_PERMISSIONS) {
 190:             if (context.checkSelfPermission(permission) != PackageManager.PERMISSION_GRANTED) {
 191:                 Log.d(TAG, "Missing permission: " + permission);
 192:                 return false;
 193:             }
 194:         }
 195:         return true;
 196:     }
 197: 
 198:     private boolean isNotificationListener() {
 199:         ComponentName component = new ComponentName(this,
 200:                 VoiceNotificationListenerService.class);
 201:         NotificationManager notificationManager = getSystemService(NotificationManager.class);
 202:         return notificationManager.isNotificationListenerAccessGranted(component);
 203:     }
 204: 
 205:     private void onSetupChanged() {
 206:         Log.d(TAG, "onSetupChanged");
 207:         int items = mListeners.beginBroadcast();
 208:         for (int i = 0; i < items; i++) {
 209:             try {
 210:                 mListeners.getBroadcastItem(i).setupChanged();
 211:             } catch (RemoteException e) {
 212:                 Log.e(TAG, "Unable to notify broadcast item "
 213:                         + mListeners.getBroadcastItem(i), e);
 214:             }
 215:         }
 216:         mListeners.finishBroadcast();
 217:         updateNotification();
 218:     }
 219: 
 220:     private void updateNotification() {
 221:         if (mNotificationManager == null) {
 222:             mNotificationManager = getSystemService(NotificationManager.class);
 223:             NotificationChannel channel = new NotificationChannel(CHANNEL_ID,
 224:                     getString(R.string.app_name), NotificationManager.IMPORTANCE_DEFAULT);
 225:             mNotificationManager.createNotificationChannel(channel);
 226:         }
 227:         if (isSetupComplete()) {
 228:             Log.d(TAG, "updateNotification(): is setup complete = true");
 229:             mNotificationManager.cancel(NOTIFICATION_ID);
 230:             return;
 231:         }
 232:         Log.d(TAG, "updateNotification(): is setup complete = false");
 233:         Intent intent = new Intent(this, SignInActivity.class);
 234:         intent.setFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
 235:         PendingIntent pendingIntent = PendingIntent.getActivity(this, 0,
 236:                 intent, PendingIntent.FLAG_UPDATE_CURRENT | PendingIntent.FLAG_IMMUTABLE);
 237: 
 238:         Notification notification = new NotificationCompat.Builder(this, CHANNEL_ID)
 239:                 .setSmallIcon(R.drawable.ic_launcher)
 240:                 .setColor(getColor(R.color.car_ui_color_accent))
 241:                 .setContentTitle(getString(R.string.notification_setup_title))
 242:                 .setContentText(getString(R.string.notification_setup_text))
 243:                 .setContentIntent(pendingIntent)
 244:                 .build();
 245: 
 246:         mNotificationManager.notify(NOTIFICATION_ID, notification);
 247:     }
 248: 
 249:     @NonNull
 250:     @Override
 251:     public Set<String> onGetSupportedVoiceActions(@NonNull Set<String> voiceActions) {
 252:         Set<String> result = new HashSet<>(voiceActions);
 253:         result.retainAll(SUPPORTED_VOICE_ACTIONS);
 254:         return mVoiceRuntime.filterSupported(result);
 255:     }
 256: 
 257: }
