  16: package com.android.car.voicecontrol.actuators;
  17: 
  18: import android.util.Log;
  19: 
  20: import com.android.car.voicecontrol.TextToSpeech;
  21: 
  22: import java.util.Arrays;
  23: import java.util.regex.Matcher;
  24: import java.util.regex.Pattern;
  25: 
  26: /**
  27:  * An actuator skill
  28:  */
  29: public class Skill {
  30:     private static final String TAG = "Mica.Skill";
  31: 
  32:     private final Pattern mPattern;
  33:     private final Action mAction;
  34: 
  35:     /**
  36:      * Code to execute when a skill is matched to a recognized speech.
  37:      */
  38:     public interface Action {
  39:         /**
  40:          * Executes the action associated with this skill. Execution receives the arguments
  41:          * detected during the skill pattern matching (see {@link Skill#Skill(String, Action)} and
  42:          * a {@link TextToSpeech} that can be used to verbalize the result.
  43:          *
  44:          * @return true if executing this action completes the user request, or false if this was
  45:          * not a good match and some other skill could be tried instead.
  46:          */
  47:         boolean execute(String[] args, TextToSpeech tts);
  48:     }
  49: 
  50:     /**
  51:      * Creates a voice control skill. In this naive implementation, skills are triggered by
  52:      * a simple regular expression matching (see {@link Pattern}) on the recognized speech.
  53:      *
  54:      * @param regexp regular expression to match against (refer to {@link Pattern} for syntax
  55:      *               details)
  56:      * @param action action to execute if the regular express matches. This is a function that
  57:      *               receives the recognized groups in the regular expression (see
  58:      *               {@link Matcher#group(int)}), and returns true if the skill is able to
  59:      *               execute the recognized command.
  60:      */
  61:     Skill(String regexp, Action action) {
  62:         mPattern = Pattern.compile(regexp, Pattern.CASE_INSENSITIVE);
  63:         mAction = action;
  64:     }
  65: 
  66:     /**
  67:      * If this skill is a good match for the recognized text, the action associated with this skill
  68:      * will be executed.
  69:      *
  70:      * @param text recognized text
  71:      * @param tts {@link TextToSpeech} that will be used to utter the result of the action,
  72:      *                                if matched.
  73:      * @return true if this is a good match for the recognized text, or false if some other skill
  74:      * should be attempted instead.
  75:      */
  76:     boolean tryExecute(String text, TextToSpeech tts) {
  77:         Matcher matcher = mPattern.matcher(text);
  78:         if (!matcher.matches()) {
  79:             Log.d(TAG, "Checking '" + text + "' against '" + mPattern.toString() + "': no match");
  80:             return false;
  81:         }
  82:         String[] arguments = new String[matcher.groupCount() + 1];
  83:         for (int i = 0; i < matcher.groupCount() + 1; i++) {
  84:             arguments[i] = matcher.group(i);
  85:         }
  86:         Log.d(TAG, "Checking '" + text + "' against '" + mPattern.toString()
  87:                 + "': matched! Arguments: " + Arrays.toString(arguments));
  88:         return mAction.execute(arguments, tts);
  89:     }
  90: }
