 115:     @GuardedBy("mLock")
 116:     private void abandonNonCriticalFocusLocked() {
 117:         if (mDelayedRequest != null) {
 118:             int audioContext = CarAudioContext.getContextForAttributes(
 119:                     mDelayedRequest.getAttributes());
 120: 
 121:             if (!isCriticalAudioContext(audioContext)) {
 122:                 sendFocusLossLocked(mDelayedRequest, AUDIOFOCUS_LOSS);
 123:                 mDelayedRequest = null;
 124:             }
 125:         }
 126: 
 127:         abandonNonCriticalEntriesLocked(mFocusLosers);
 128:         abandonNonCriticalEntriesLocked(mFocusHolders);
