 131:     @GuardedBy("mLock")
 132:     private void abandonNonCriticalEntriesLocked(Map<String, FocusEntry> entries) {
 133:         List<String> clientsToRemove = new ArrayList<>();
 134:         for (FocusEntry holderEntry : entries.values()) {
 135:             if (isCriticalAudioContext(holderEntry.getAudioContext())) {
 136:                 continue;
 137:             }
 138: 
 139:             sendFocusLossLocked(holderEntry.getAudioFocusInfo(), AUDIOFOCUS_LOSS);
 140:             clientsToRemove.add(holderEntry.getAudioFocusInfo().getClientId());
 141:         }
 142: 
 143:         for (int i = 0; i < clientsToRemove.size(); i++) {
 144:             String clientId = clientsToRemove.get(i);
 145:             FocusEntry removedEntry = entries.remove(clientId);
 146:             removeBlockerAndRestoreUnblockedWaitersLocked(removedEntry);
 147:         }
 148:     }
