 150:     // This sends a focus loss message to the targeted requester.
 151:     private void sendFocusLossLocked(AudioFocusInfo loser, int lossType) {
 152:         int result = mAudioManager.dispatchAudioFocusChange(loser, lossType,
 153:                 mAudioPolicy);
 154:         if (result != AUDIOFOCUS_REQUEST_GRANTED) {
 155:             // TODO:  Is this actually an error, or is it okay for an entry in the focus stack
 156:             // to NOT have a listener?  If that's the case, should we even keep it in the focus
 157:             // stack?
 158:             Slogf.e(TAG, "Failure to signal loss of audio focus with error: " + result);
 159:         }
 160: 
 161:         logFocusEvent("sendFocusLoss for client " + loser.getClientId()
 162:                 + " with loss type " + focusEventToString(lossType)
 163:                 + " resulted in " + focusRequestResponseToString(result));
 164:     }
