 166:     /** @see AudioManager#requestAudioFocus(AudioManager.OnAudioFocusChangeListener, int, int, int) */
 167:     // Note that we replicate most, but not all of the behaviors of the default MediaFocusControl
 168:     // engine as of Android P.
 169:     // Besides the interaction matrix which allows concurrent focus for multiple requestors, which
 170:     // is the reason for this module, we also treat repeated requests from the same clientId
 171:     // slightly differently.
 172:     // If a focus request for the same listener (clientId) is received while that listener is
 173:     // already in the focus stack, we REJECT it outright unless it is for the same USAGE.
 174:     // If it is for the same USAGE, we replace the old request with the new one.
 175:     // The default audio framework's behavior is to remove the previous entry in the stack (no-op
 176:     // if the requester is already holding focus).
 177:     @GuardedBy("mLock")
 178:     private int evaluateFocusRequestLocked(AudioFocusInfo afi) {
 179:         Slogf.i(TAG, "Evaluating " + focusEventToString(afi.getGainRequest())
 180:                 + " request for client " + afi.getClientId()
 181:                 + " with usage " + usageToString(afi.getAttributes().getUsage()));
 182: 
 183:         if (mIsFocusRestricted) {
 184:             int audioContext = CarAudioContext.getContextForAttributes(afi.getAttributes());
 185:             if (!isCriticalAudioContext(audioContext)) {
 186:                 return AUDIOFOCUS_REQUEST_FAILED;
 187:             }
 188:         }
 189: 
 190:         // Is this a request for premanant focus?
 191:         // AUDIOFOCUS_GAIN_TRANSIENT_EXCLUSIVE -- Means Notifications should be denied
 192:         // AUDIOFOCUS_GAIN_TRANSIENT -- Means current focus holders should get transient loss
 193:         // AUDIOFOCUS_GAIN_TRANSIENT_MAY_DUCK -- Means other can duck (no loss message from us)
 194:         // NOTE:  We expect that in practice it will be permanent for all media requests and
 195:         //        transient for everything else, but that isn't currently an enforced requirement.
 196:         final boolean permanent =
 197:                 (afi.getGainRequest() == AUDIOFOCUS_GAIN);
 198:         final boolean allowDucking =
 199:                 (afi.getGainRequest() == AUDIOFOCUS_GAIN_TRANSIENT_MAY_DUCK);
 200: 
 201:         boolean delayFocusForCurrentRequest = false;
 202: 
 203:         int requestedContext = CarAudioContext.getContextForAttributes(afi.getAttributes());
 204: 
 205:         // If we happen to find entries that this new request should replace, we'll store them here.
 206:         // This happens when a client makes a second AF request on the same listener.
 207:         // After we've granted audio focus to our current request, we'll abandon these requests.
 208:         FocusEntry replacedCurrentEntry = null;
 209:         FocusEntry replacedBlockedEntry = null;
 210: 
 211:         boolean allowDelayedFocus = canReceiveDelayedFocus(afi);
 212: 
 213:         // We don't allow sharing listeners (client IDs) between two concurrent requests
 214:         // (because the app would have no way to know to which request a later event applied)
 215:         if (mDelayedRequest != null && afi.getClientId().equals(mDelayedRequest.getClientId())) {
 216:             int delayedRequestedContext = CarAudioContext.getContextForAttributes(
 217:                     mDelayedRequest.getAttributes());
 218:             // If it is for a different context then reject
 219:             if (delayedRequestedContext != requestedContext) {
 220:                 // Trivially reject a request for a different USAGE
 221:                 Slogf.e(TAG, "Client %s has already delayed requested focus for %s - cannot request"
 222:                         + " focus for %s on same listener.", mDelayedRequest.getClientId(),
 223:                         usageToString(mDelayedRequest.getAttributes().getUsage()),
 224:                         usageToString(afi.getAttributes().getUsage()));
 225:                 return AUDIOFOCUS_REQUEST_FAILED;
 226:             }
 227:         }
 228: 
 229:         // Scan all active and pending focus requests.  If any should cause rejection of
 230:         // this new request, then we're done.  Keep a list of those against whom we're exclusive
 231:         // so we can update the relationships if/when we are sure we won't get rejected.
 232:         Slogf.i(TAG, "Scanning focus holders...");
 233:         final ArrayList<FocusEntry> losers = new ArrayList<FocusEntry>();
 234:         for (FocusEntry entry : mFocusHolders.values()) {
 235:             Slogf.d(TAG, "Evaluating focus holder: " + entry.getClientId());
 236: 
 237:             // If this request is for Notifications and a current focus holder has specified
 238:             // AUDIOFOCUS_GAIN_TRANSIENT_EXCLUSIVE, then reject the request.
 239:             // This matches the hardwired behavior in the default audio policy engine which apps
 240:             // might expect (The interaction matrix doesn't have any provision for dealing with
 241:             // override flags like this).
 242:             if ((requestedContext == CarAudioContext.NOTIFICATION)
 243:                     && (entry.getAudioFocusInfo().getGainRequest()
 244:                     == AUDIOFOCUS_GAIN_TRANSIENT_EXCLUSIVE)) {
 245:                 return AUDIOFOCUS_REQUEST_FAILED;
 246:             }
 247: 
 248:             // We don't allow sharing listeners (client IDs) between two concurrent requests
 249:             // (because the app would have no way to know to which request a later event applied)
 250:             if (afi.getClientId().equals(entry.getAudioFocusInfo().getClientId())) {
 251:                 if ((entry.getAudioContext() == requestedContext)
 252:                         || canSwapCallOrRingerClientRequest(afi.getClientId(),
 253:                         entry.getAudioContext(), requestedContext)) {
 254:                     // This is a request from a current focus holder.
 255:                     // Abandon the previous request (without sending a LOSS notification to it),
 256:                     // and don't check the interaction matrix for it.
 257:                     Slogf.i(TAG, "Replacing accepted request from same client: %s",
 258:                             afi.getClientId());
 259:                     replacedCurrentEntry = entry;
 260:                     continue;
 261:                 } else {
 262:                     // Trivially reject a request for a different USAGE
 263:                     Slogf.e(TAG, "Client %s has already requested focus for %s - cannot request "
 264:                             + "focus for %s on same listener.", entry.getClientId(),
 265:                             usageToString(entry.getAudioFocusInfo().getAttributes().getUsage()),
 266:                             usageToString(afi.getAttributes().getUsage()));
 267:                     return AUDIOFOCUS_REQUEST_FAILED;
 268:                 }
 269:             }
 270: 
 271:             int interactionResult = mFocusInteraction.evaluateRequest(requestedContext, entry,
 272:                     losers, allowDucking, allowDelayedFocus);
 273:             if (interactionResult == AUDIOFOCUS_REQUEST_FAILED) {
 274:                 return interactionResult;
 275:             }
 276:             if (interactionResult == AUDIOFOCUS_REQUEST_DELAYED) {
 277:                 delayFocusForCurrentRequest = true;
 278:             }
 279:         }
 280:         Slogf.i(TAG, "Scanning those who've already lost focus...");
 281:         final ArrayList<FocusEntry> blocked = new ArrayList<FocusEntry>();
 282:         for (FocusEntry entry : mFocusLosers.values()) {
 283:             Slogf.i(TAG, entry.getAudioFocusInfo().getClientId());
 284: 
 285:             // If this request is for Notifications and a pending focus holder has specified
 286:             // AUDIOFOCUS_GAIN_TRANSIENT_EXCLUSIVE, then reject the request
 287:             if ((requestedContext == CarAudioContext.NOTIFICATION)
 288:                     && (entry.getAudioFocusInfo().getGainRequest()
 289:                     == AUDIOFOCUS_GAIN_TRANSIENT_EXCLUSIVE)) {
 290:                 return AUDIOFOCUS_REQUEST_FAILED;
 291:             }
 292: 
 293:             // We don't allow sharing listeners (client IDs) between two concurrent requests
 294:             // (because the app would have no way to know to which request a later event applied)
 295:             if (afi.getClientId().equals(entry.getAudioFocusInfo().getClientId())) {
 296:                 if (entry.getAudioContext() == requestedContext) {
 297:                     // This is a repeat of a request that is currently blocked.
 298:                     // Evaluate it as if it were a new request, but note that we should remove
 299:                     // the old pending request, and move it.
 300:                     // We do not want to evaluate the new request against itself.
 301:                     Slogf.i(TAG, "Replacing pending request from same client");
 302:                     replacedBlockedEntry = entry;
 303:                     continue;
 304:                 } else {
 305:                     // Trivially reject a request for a different USAGE
 306:                     Slogf.e(TAG, "Client %s has already requested focus for %s - cannot request "
 307:                             + "focus for %s on same listener.", entry.getClientId(),
 308:                             usageToString(entry.getAudioFocusInfo().getAttributes().getUsage()),
 309:                             usageToString(afi.getAttributes().getUsage()));
 310:                     return AUDIOFOCUS_REQUEST_FAILED;
 311:                 }
 312:             }
 313: 
 314:             int interactionResult = mFocusInteraction
 315:                     .evaluateRequest(requestedContext, entry, blocked, allowDucking,
 316:                             allowDelayedFocus);
 317:             if (interactionResult == AUDIOFOCUS_REQUEST_FAILED) {
 318:                 return interactionResult;
 319:             }
 320:             if (interactionResult == AUDIOFOCUS_REQUEST_DELAYED) {
 321:                 delayFocusForCurrentRequest = true;
 322:             }
 323:         }
 324: 
 325: 
 326:         // Now that we've decided we'll grant focus, construct our new FocusEntry
 327:         FocusEntry newEntry = new FocusEntry(afi, requestedContext, mPackageManager);
 328: 
 329:         // These entries have permanently lost focus as a result of this request, so they
 330:         // should be removed from all blocker lists.
 331:         ArrayList<FocusEntry> permanentlyLost = new ArrayList<>();
 332: 
 333:         if (replacedCurrentEntry != null) {
 334:             mFocusHolders.remove(replacedCurrentEntry.getClientId());
 335:             permanentlyLost.add(replacedCurrentEntry);
 336:         }
 337:         if (replacedBlockedEntry != null) {
 338:             mFocusLosers.remove(replacedBlockedEntry.getClientId());
 339:             permanentlyLost.add(replacedBlockedEntry);
 340:         }
 341: 
 342: 
 343:         // Now that we're sure we'll accept this request, update any requests which we would
 344:         // block but are already out of focus but waiting to come back
 345:         for (FocusEntry entry : blocked) {
 346:             // If we're out of focus it must be because somebody is blocking us
 347:             assert !entry.isUnblocked();
 348: 
 349:             if (permanent) {
 350:                 // This entry has now lost focus forever
 351:                 sendFocusLossLocked(entry.getAudioFocusInfo(), AUDIOFOCUS_LOSS);
 352:                 entry.setDucked(false);
 353:                 final FocusEntry deadEntry = mFocusLosers.remove(
 354:                         entry.getAudioFocusInfo().getClientId());
 355:                 assert deadEntry != null;
 356:                 permanentlyLost.add(entry);
 357:             } else {
 358:                 if (!allowDucking && entry.isDucked()) {
 359:                     // This entry was previously allowed to duck, but can no longer do so.
 360:                     Slogf.i(TAG, "Converting duckable loss to non-duckable for "
 361:                             + entry.getClientId());
 362:                     sendFocusLossLocked(entry.getAudioFocusInfo(), AUDIOFOCUS_LOSS_TRANSIENT);
 363:                     entry.setDucked(false);
 364:                 }
 365:                 // Note that this new request is yet one more reason we can't (yet) have focus
 366:                 entry.addBlocker(newEntry);
 367:             }
 368:         }
 369: 
 370:         // Notify and update any requests which are now losing focus as a result of the new request
 371:         for (FocusEntry entry : losers) {
 372:             // If we have focus (but are about to loose it), nobody should be blocking us yet
 373:             assert entry.isUnblocked();
 374: 
 375:             int lossType;
 376:             if (permanent) {
 377:                 lossType = AUDIOFOCUS_LOSS;
 378:             } else if (allowDucking && entry.receivesDuckEvents()) {
 379:                 lossType = AUDIOFOCUS_LOSS_TRANSIENT_CAN_DUCK;
 380:                 entry.setDucked(true);
 381:             } else {
 382:                 lossType = AUDIOFOCUS_LOSS_TRANSIENT;
 383:             }
 384:             sendFocusLossLocked(entry.getAudioFocusInfo(), lossType);
 385: 
 386:             // The entry no longer holds focus, so take it out of the holders list
 387:             mFocusHolders.remove(entry.getAudioFocusInfo().getClientId());
 388: 
 389:             if (permanent) {
 390:                 permanentlyLost.add(entry);
 391:             } else {
 392:                 // Add ourselves to the list of requests waiting to get focus back and
 393:                 // note why we lost focus so we can tell when it's time to get it back
 394:                 mFocusLosers.put(entry.getAudioFocusInfo().getClientId(), entry);
 395:                 entry.addBlocker(newEntry);
 396:             }
 397:         }
 398: 
 399:         // Now that all new blockers have been added, clear out any other requests that have been
 400:         // permanently lost as a result of this request. Treat them as abandoned - if they're on
 401:         // any blocker lists, remove them. If any focus requests become unblocked as a result,
 402:         // re-grant them. (This can happen when a GAIN_TRANSIENT_MAY_DUCK request replaces a
 403:         // GAIN_TRANSIENT request from the same listener.)
 404:         for (FocusEntry entry : permanentlyLost) {
 405:             Slogf.d(TAG, "Cleaning up entry " + entry.getClientId());
 406:             removeBlockerAndRestoreUnblockedWaitersLocked(entry);
 407:         }
 408: 
 409:         if (delayFocusForCurrentRequest) {
 410:             swapDelayedAudioFocusRequestLocked(afi);
 411:             return AUDIOFOCUS_REQUEST_DELAYED;
 412:         }
 413: 
 414:         mFocusHolders.put(afi.getClientId(), newEntry);
 415: 
 416:         Slogf.i(TAG, "AUDIOFOCUS_REQUEST_GRANTED");
 417:         return AUDIOFOCUS_REQUEST_GRANTED;
 418:     }
