 420:     private static boolean canSwapCallOrRingerClientRequest(String clientId,
 421:             @AudioContext int currentAudioContext,
 422:             @AudioContext int requestedContext) {
 423:         return isCallFocusRequestClientId(clientId)
 424:                 && isRingerOrCallAudioContext(currentAudioContext)
 425:                 && isRingerOrCallAudioContext(requestedContext);
 426:     }
 427: 
 428:     private static boolean isRingerOrCallAudioContext(@AudioContext int audioContext) {
 429:         return CarAudioContext.isRingerOrCallContext(audioContext);
 430:     }
