 432:     @Override
 433:     public void onAudioFocusRequest(AudioFocusInfo afi, int requestResult) {
 434:         int response;
 435:         AudioPolicy policy;
 436:         synchronized (mLock) {
 437:             policy = mAudioPolicy;
 438:             response = evaluateFocusRequestLocked(afi);
 439:         }
 440: 
 441:         // Post our reply for delivery to the original focus requester
 442:         mAudioManager.setFocusRequestResult(afi, response, policy);
 443:         logFocusEvent("onAudioFocusRequest for client " + afi.getClientId()
 444:                 + " with gain type " + focusEventToString(afi.getGainRequest())
 445:                 + " resulted in " + focusRequestResponseToString(response));
 446:     }
 447: 
 448:     private void swapDelayedAudioFocusRequestLocked(AudioFocusInfo afi) {
 449:         // If we are swapping to a different client then send the focus loss signal
 450:         if (mDelayedRequest != null
 451:                 && !afi.getClientId().equals(mDelayedRequest.getClientId())) {
 452:             sendFocusLossLocked(mDelayedRequest, AUDIOFOCUS_LOSS);
 453:         }
 454:         mDelayedRequest = afi;
 455:     }
 456: 
 457:     private boolean canReceiveDelayedFocus(AudioFocusInfo afi) {
 458:         if (afi.getGainRequest() != AUDIOFOCUS_GAIN) {
 459:             return false;
 460:         }
 461:         return (afi.getFlags() & AUDIOFOCUS_FLAG_DELAY_OK) == AUDIOFOCUS_FLAG_DELAY_OK;
 462:     }
 463: 
 464:     /**
 465:      * @see AudioManager#abandonAudioFocus(AudioManager.OnAudioFocusChangeListener, AudioAttributes)
 466:      * Note that we'll get this call for a focus holder that dies while in the focus stack, so
 467:      * we don't need to watch for death notifications directly.
 468:      * */
 469:     @Override
 470:     public void onAudioFocusAbandon(AudioFocusInfo afi) {
 471:         logFocusEvent("onAudioFocusAbandon for client " + afi.getClientId());
 472:         synchronized (mLock) {
 473:             FocusEntry deadEntry = removeFocusEntryLocked(afi);
 474: 
 475:             if (deadEntry != null) {
 476:                 removeBlockerAndRestoreUnblockedWaitersLocked(deadEntry);
 477:             } else {
 478:                 removeDelayedAudioFocusRequestLocked(afi);
 479:             }
 480:         }
 481:     }
 482: 
 483:     private void removeDelayedAudioFocusRequestLocked(AudioFocusInfo afi) {
 484:         if (mDelayedRequest != null && afi.getClientId().equals(mDelayedRequest.getClientId())) {
 485:             mDelayedRequest = null;
 486:         }
 487:     }
 488: 
 489:     /**
 490:      * Remove Focus entry from focus holder or losers entry lists
 491:      * @param afi Audio Focus Info to remove
 492:      * @return Removed Focus Entry
 493:      */
 494:     private FocusEntry removeFocusEntryLocked(AudioFocusInfo afi) {
 495:         Slogf.i(TAG, "removeFocusEntry " + afi.getClientId());
 496: 
 497:         // Remove this entry from our active or pending list
 498:         FocusEntry deadEntry = mFocusHolders.remove(afi.getClientId());
 499:         if (deadEntry == null) {
 500:             deadEntry = mFocusLosers.remove(afi.getClientId());
 501:             if (deadEntry == null) {
 502:                 // Caller is providing an unrecognzied clientId!?
 503:                 Slogf.w(TAG, "Audio focus abandoned by unrecognized client id: "
 504:                         + afi.getClientId());
 505:                 // This probably means an app double released focused for some reason.  One
 506:                 // harmless possibility is a race between an app being told it lost focus and the
 507:                 // app voluntarily abandoning focus.  More likely the app is just sloppy.  :)
 508:                 // The more nefarious possibility is that the clientId is actually corrupted
 509:                 // somehow, in which case we might have a real focus entry that we're going to fail
 510:                 // to remove. If that were to happen, I'd expect either the app to swallow it
 511:                 // silently, or else take unexpected action (eg: resume playing spontaneously), or
 512:                 // else to see "Failure to signal ..." gain/loss error messages in the log from
 513:                 // this module when a focus change tries to take action on a truly zombie entry.
 514:             }
 515:         }
 516:         return deadEntry;
 517:     }
 518: 
 519:     @GuardedBy("mLock")
 520:     private void removeBlockerAndRestoreUnblockedWaitersLocked(FocusEntry deadEntry) {
 521:         attemptToGainFocusForDelayedAudioFocusRequestLocked();
 522:         removeBlockerAndRestoreUnblockedFocusLosersLocked(deadEntry);
 523:     }
 524: 
 525:     @GuardedBy("mLock")
 526:     private void attemptToGainFocusForDelayedAudioFocusRequestLocked() {
 527:         if (mDelayedRequest == null) {
 528:             return;
 529:         }
 530: 
 531:         int delayedFocusRequestResults = evaluateFocusRequestLocked(mDelayedRequest);
 532:         if (delayedFocusRequestResults == AUDIOFOCUS_REQUEST_GRANTED) {
 533:             FocusEntry focusEntry = mFocusHolders.get(mDelayedRequest.getClientId());
 534:             mDelayedRequest = null;
 535:             if (dispatchFocusGainedLocked(focusEntry.getAudioFocusInfo())
 536:                     == AUDIOFOCUS_REQUEST_FAILED) {
 537:                 Slogf.e(TAG, "Failure to signal gain of audio focus gain for "
 538:                         + "delayed focus clientId " + focusEntry.getClientId());
 539:                 mFocusHolders.remove(focusEntry.getClientId());
 540:                 removeBlockerFromBlockedFocusLosersLocked(focusEntry);
 541:                 sendFocusLossLocked(focusEntry.getAudioFocusInfo(),
 542:                         AUDIOFOCUS_LOSS);
 543:                 logFocusEvent("Did not gained delayed audio focus for "
 544:                         + focusEntry.getClientId());
 545:             }
 546:         }
 547:     }
 548: 
 549:     /**
 550:      * Removes the dead entry from blocked waiters but does not send focus gain signal
 551:      */
 552:     private void removeBlockerFromBlockedFocusLosersLocked(FocusEntry deadEntry) {
 553:         // Remove this entry from the blocking list of any pending requests
 554:         Iterator<FocusEntry> it = mFocusLosers.values().iterator();
 555:         while (it.hasNext()) {
 556:             FocusEntry entry = it.next();
 557:             // Remove the retiring entry from all blocker lists
 558:             entry.removeBlocker(deadEntry);
 559:         }
 560:     }
 561: 
 562:     /**
 563:      * Removes the dead entry from blocked waiters and sends focus gain signal
 564:      */
 565:     private void removeBlockerAndRestoreUnblockedFocusLosersLocked(FocusEntry deadEntry) {
 566:         // Remove this entry from the blocking list of any pending requests
 567:         Iterator<FocusEntry> it = mFocusLosers.values().iterator();
 568:         while (it.hasNext()) {
 569:             FocusEntry entry = it.next();
 570: 
 571:             // Remove the retiring entry from all blocker lists
 572:             entry.removeBlocker(deadEntry);
 573: 
 574:             // Any entry whose blocking list becomes empty should regain focus
 575:             if (entry.isUnblocked()) {
 576:                 Slogf.i(TAG, "Restoring unblocked entry " + entry.getClientId());
 577:                 // Pull this entry out of the focus losers list
 578:                 it.remove();
 579: 
 580:                 // Add it back into the focus holders list
 581:                 mFocusHolders.put(entry.getClientId(), entry);
 582: 
 583:                 dispatchFocusGainedLocked(entry.getAudioFocusInfo());
 584:             }
 585:         }
 586:     }
 587: 
 588:     /**
 589:      * Dispatch focus gain
 590:      * @param afi Audio focus info
 591:      * @return {@link AUDIOFOCUS_REQUEST_GRANTED} if focus is dispatched successfully
 592:      */
 593:     private int dispatchFocusGainedLocked(AudioFocusInfo afi) {
 594:         // Send the focus (re)gain notification
 595:         int result = mAudioManager.dispatchAudioFocusChange(afi, AUDIOFOCUS_GAIN, mAudioPolicy);
 596:         if (result != AUDIOFOCUS_REQUEST_GRANTED) {
 597:             // TODO:  Is this actually an error, or is it okay for an entry in the focus
 598:             // stack to NOT have a listener?  If that's the case, should we even keep
 599:             // it in the focus stack?
 600:             Slogf.e(TAG, "Failure to signal gain of audio focus with error: " + result);
 601:         }
 602: 
 603:         logFocusEvent("dispatchFocusGainedLocked for client " + afi.getClientId()
 604:                         + " with gain type " + focusEventToString(afi.getGainRequest())
 605:                         + " resulted in " + focusRequestResponseToString(result));
 606:         return result;
 607:     }
 608: 
 609:     /**
 610:      * Query the current list of focus loser for uid
 611:      * @param uid uid to query current focus loser
 612:      * @return list of current focus losers for uid
 613:      */
 614:     ArrayList<AudioFocusInfo> getAudioFocusLosersForUid(int uid) {
 615:         return getAudioFocusListForUid(uid, mFocusLosers);
 616:     }
 617: 
 618:     /**
 619:      * Query the current list of focus holders for uid
 620:      * @param uid uid to query current focus holders
 621:      * @return list of current focus holders that for uid
 622:      */
 623:     ArrayList<AudioFocusInfo> getAudioFocusHoldersForUid(int uid) {
 624:         return getAudioFocusListForUid(uid, mFocusHolders);
 625:     }
 626: 
 627:     List<AudioFocusInfo> getAudioFocusHolders() {
 628:         List<AudioFocusInfo> focusHolders = new ArrayList<>();
 629:         synchronized (mLock) {
 630:             for (FocusEntry entry : mFocusHolders.values()) {
 631:                 focusHolders.add(entry.getAudioFocusInfo());
 632:             }
 633:             return focusHolders;
 634:         }
 635:     }
 636: 
 637:     /**
 638:      * Query input list for matching uid
 639:      * @param uid uid to match in map
 640:      * @param mapToQuery map to query for uid info
 641:      * @return list of audio focus info that match uid
 642:      */
 643:     private ArrayList<AudioFocusInfo> getAudioFocusListForUid(int uid,
 644:             Map<String, FocusEntry> mapToQuery) {
 645:         ArrayList<AudioFocusInfo> matchingInfoList = new ArrayList<>();
 646:         synchronized (mLock) {
 647:             for (String clientId : mapToQuery.keySet()) {
 648:                 AudioFocusInfo afi = mapToQuery.get(clientId).getAudioFocusInfo();
 649:                 if (afi.getClientUid() == uid) {
 650:                     matchingInfoList.add(afi);
 651:                 }
 652:             }
 653:         }
 654:         return matchingInfoList;
 655:     }
 656: 
 657:     /**
 658:      * Remove the audio focus info, if entry is still active
 659:      * dispatch lose focus transient to listeners
 660:      * @param afi Audio Focus info to remove
 661:      */
 662:     void removeAudioFocusInfoAndTransientlyLoseFocus(AudioFocusInfo afi) {
 663:         synchronized (mLock) {
 664:             FocusEntry deadEntry = removeFocusEntryLocked(afi);
 665:             if (deadEntry != null) {
 666:                 sendFocusLossLocked(deadEntry.getAudioFocusInfo(),
 667:                         AUDIOFOCUS_LOSS_TRANSIENT);
 668:                 removeBlockerAndRestoreUnblockedWaitersLocked(deadEntry);
 669:             }
 670:         }
 671:     }
 672: 
 673:     /**
 674:      * Reevaluate focus request and regain focus
 675:      * @param afi audio focus info to reevaluate
 676:      * @return {@link AUDIOFOCUS_REQUEST_GRANTED} if focus is granted
 677:      */
 678:     int reevaluateAndRegainAudioFocus(AudioFocusInfo afi) {
 679:         int results;
 680:         synchronized (mLock) {
 681:             results = evaluateFocusRequestLocked(afi);
 682:             if (results == AUDIOFOCUS_REQUEST_GRANTED) {
 683:                 results = dispatchFocusGainedLocked(afi);
 684:             }
 685:         }
 686: 
 687:         return results;
 688:     }
 689: 
 690:     @ExcludeFromCodeCoverageGeneratedReport(reason = DUMP_INFO)
 691:     public void dump(IndentingPrintWriter writer) {
 692:         synchronized (mLock) {
 693:             writer.println("*CarAudioFocus*");
 694:             writer.increaseIndent();
 695:             writer.printf("Is focus restricted? %b\n", mIsFocusRestricted);
 696:             writer.println();
 697:             mFocusInteraction.dump(writer);
 698: 
 699:             writer.println("Current Focus Holders:");
 700:             writer.increaseIndent();
 701:             for (String clientId : mFocusHolders.keySet()) {
 702:                 mFocusHolders.get(clientId).dump(writer);
 703:             }
 704:             writer.decreaseIndent();
 705: 
 706:             writer.println("Transient Focus Losers:");
 707:             writer.increaseIndent();
 708:             for (String clientId : mFocusLosers.keySet()) {
 709:                 mFocusLosers.get(clientId).dump(writer);
 710:             }
 711:             writer.decreaseIndent();
 712: 
 713:             writer.printf("Queued Delayed Focus: %s\n",
 714:                     mDelayedRequest == null ? "None" : mDelayedRequest.getClientId());
 715: 
 716:             writer.println("Focus Events:");
 717:             writer.increaseIndent();
 718:             mFocusEventLogger.dump(writer);
 719:             writer.decreaseIndent();
 720: 
 721:             writer.decreaseIndent();
 722:         }
 723:     }
 724: 
 725:     private static String focusEventToString(int focusEvent) {
 726:         switch (focusEvent) {
 727:             case AUDIOFOCUS_GAIN:
 728:                 return "GAIN";
 729:             case AUDIOFOCUS_GAIN_TRANSIENT:
 730:                 return "GAIN_TRANSIENT";
 731:             case AUDIOFOCUS_GAIN_TRANSIENT_EXCLUSIVE:
 732:                 return "GAIN_TRANSIENT_EXCLUSIVE";
 733:             case AUDIOFOCUS_GAIN_TRANSIENT_MAY_DUCK:
 734:                 return "GAIN_TRANSIENT_MAY_DUCK";
 735:             case AUDIOFOCUS_LOSS:
 736:                 return "LOSS";
 737:             case AUDIOFOCUS_LOSS_TRANSIENT:
 738:                 return "LOSS_TRANSIENT";
 739:             case AUDIOFOCUS_LOSS_TRANSIENT_CAN_DUCK:
 740:                 return "LOSS_TRANSIENT_CAN_DUCK";
 741:             default:
 742:                 return "unknown event " + focusEvent;
 743:         }
 744:     }
 745: 
 746:     private static String focusRequestResponseToString(int response) {
 747:         if (response == AUDIOFOCUS_REQUEST_GRANTED) {
 748:             return "REQUEST_GRANTED";
 749:         } else if (response == AUDIOFOCUS_REQUEST_FAILED) {
 750:             return "REQUEST_FAILED";
 751:         }
 752:         return "REQUEST_DELAYED";
 753:     }
 754: 
 755:     private void logFocusEvent(String log) {
 756:         mFocusEventLogger.log(log);
 757:         Slogf.i(TAG, log);
 758:     }
 759: 
 760:     /**
 761:      * Returns the focus interaction for this car focus instance.
 762:      */
 763:     public FocusInteraction getFocusInteraction() {
 764:         return mFocusInteraction;
 765:     }
 766: }

