 452:     private MutingInfo verifyOnDevicesToMuteChangeCalled(int audioZoneId) throws Exception {
 453:         ArgumentCaptor<MutingInfo[]> captor = ArgumentCaptor.forClass(MutingInfo[].class);
 454:         verify(mAudioControl).onDevicesToMuteChange(captor.capture());
 455:         for (MutingInfo info : captor.getValue()) {
 456:             if (info.zoneId != audioZoneId) {
 457:                 continue;
 458:             }
 459:             return info;
 460:         }
 461:         return null;
 462:     }
 463: 
 464:     private static final class MutingInfoBuilder {
 465:         private final int mZoneId;
 466:         private String[] mAddressesToMute;
 467:         private String[] mAddressesToUnMute;
 468: 
 469:         MutingInfoBuilder(int zoneId) {
 470:             mZoneId = zoneId;
 471:         }
 472: 
 473:         MutingInfoBuilder setMutedAddresses(String... addressesToMute) {
 474:             mAddressesToMute = addressesToMute;
 475:             return this;
 476:         }
 477: 
 478:         MutingInfoBuilder setUnMutedAddresses(String... addressesToUnMute) {
 479:             mAddressesToUnMute = addressesToUnMute;
 480:             return this;
 481:         }
 482: 
 483:         MutingInfo build() {
 484:             MutingInfo info = new MutingInfo();
 485:             info.zoneId = mZoneId;
 486:             info.deviceAddressesToMute = mAddressesToMute;
 487:             info.deviceAddressesToUnmute = mAddressesToUnMute;
 488:             return info;
 489:         }
 490:     }
